```yaml
name: Publish Daily Repo Status

on:
  schedule:
    - cron: '0 0 * * *'  # Runs daily at midnight UTC

permissions:
  contents: write
  pull-requests: read

jobs:
  generate-status:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Generate daily status report
        uses: actions/github-script@v6
        with:
          script: |
            const now = new Date();
            const twoDaysAgo = new Date(now.getTime() - 48 * 60 * 60 * 1000);

            // Fetch merged PRs in the last 48 hours
            const mergedPRs = await github.paginate(github.rest.pulls.list, {
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'closed',
              sort: 'updated',
              direction: 'desc',
              per_page: 100
            });
            const recentMerged = mergedPRs.filter(pr => pr.merged_at && new Date(pr.merged_at) >= twoDaysAgo);

            // Fetch open PRs
            const openPRs = await github.paginate(github.rest.pulls.list, {
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'open',
              per_page: 100
            });

            const dateStr = now.toISOString().split('T')[0];
            let md = `## ✅ Recently Merged (Last 48 Hours)\n\n| # | Title | Author |\n|---|-------|--------|\n`;
            recentMerged.forEach(pr => {
              md += `| [#${pr.number}](${pr.html_url}) | ${pr.title} | @${pr.user.login} |\n`;
            });

            md += `\n## 🔄 Open Pull Requests (Needs Attention)\n\n| # | Title | Author |\n|---|-------|--------|\n`;
            openPRs.forEach(pr => {
              md += `| [#${pr.number}](${pr.html_url}) | ${pr.title} | @${pr.user.login} |\n`;
            });

            const fs = require('fs');
            fs.writeFileSync('daily-status.md', md);

      - name: Commit status report
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "github-actions[bot]@users.noreply.github.com"
          git add daily-status.md
          git commit -m "Update daily status report ${dateStr}" || echo "No changes to commit"
          git push

      - name: Publish to Microsoft Skills
        run: |
          echo "Publishing the daily status report to Microsoft Skills (placeholder action)"
